/bin/bash -lc "node --input-type=module <<'EOF'
import { spawnSync } from 'node:child_process';

const cases = [
  [],
  ['--help'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--b', '2', '--c', '1', '--d', '4', '--e', '5'],
  ['--a', 'x', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4'],
  ['--a=1', '--b=2', '--c=3', '--d=4', '--e=5'],
  ['--a', '-1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--a', '9', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1_0', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--z', '9', '--help'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '--z', '9'],
  ['9', '--help'],
  ['--a', '1', '--help'],
  ['--a', '--help'],
  ['--a', '+1e2', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '-1e2', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
];

let ok = true;
for (const args of cases) {
  const py = spawnSync('/workspace/dataset/test5_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test5.mjs', ...args], { encoding: 'utf8' });

  const normalizedPyStderr = py.stderr.replaceAll('test5_executable', 'test5.mjs');
  const match = py.status === js.status && py.stdout === js.stdout && normalizedPyStderr === js.stderr;

  if ("'!match) {
    ok = false;
    console.log(`mismatch: ${JSON.stringify(args)}`);
    console.log(JSON.stringify({ pyStatus: py.status, pyStdout: py.stdout, pyStderr: normalizedPyStderr, jsStatus: js.status, jsStdout: js.stdout, jsStderr: js.stderr }, null, 2));
  }
}

if (ok) {
  console.log('"'all comparison cases matched');
}
EOF"

